// Core tests: the 15 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every expected value below was computed by hand
// from the SPEC's rules (exact rational M, one half-up rounding per
// output).

import assert from "node:assert/strict";
import test from "node:test";
import { formatAmount, run } from "../public/js/core/salary.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { sourceBasis: "monthly", amount: "40000", bonusMonths: "0" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("each basis cap holds exactly at the limit and fails just above it", () => {
  // monthly cap 99,999,999 (the max fixture also covers it with bonus 24).
  assert.equal(run({ sourceBasis: "monthly", amount: "99999999", bonusMonths: "0" }).ok, true);
  assert.deepEqual(errorOf({ sourceBasis: "monthly", amount: "100000000", bonusMonths: "0" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  // daily cap 9,999,999; daily "10000000" is over.
  assert.equal(run({ sourceBasis: "daily", amount: "9999999", bonusMonths: "0" }).ok, true);
  assert.deepEqual(errorOf({ sourceBasis: "daily", amount: "10000000", bonusMonths: "0" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  // hourly cap 999,999 applies to the value, so "999999.99" is over too.
  assert.equal(run({ sourceBasis: "hourly", amount: "999999", bonusMonths: "0" }).ok, true);
  assert.deepEqual(errorOf({ sourceBasis: "hourly", amount: "999999.99", bonusMonths: "0" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  // annual cap 999,999,999.
  assert.equal(run({ sourceBasis: "annual", amount: "999999999", bonusMonths: "0" }).ok, true);
  assert.deepEqual(errorOf({ sourceBasis: "annual", amount: "1000000000", bonusMonths: "0" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
});

test("the SPEC's legal maximum: daily cap with 24 bonus months", () => {
  // M = 9,999,999 x 30 = 299,999,970 exactly; annualTotal = M x 36 =
  // 10,799,998,920, the largest output the SPEC allows.
  assert.deepEqual(run({ sourceBasis: "daily", amount: "9999999", bonusMonths: "24" }), {
    ok: true,
    result: {
      monthly: 299999970,
      daily: 9999999,
      hourly: 1250000,
      annualBase: 3599999640,
      bonusAmount: 7199999280,
      annualTotal: 10799998920,
    },
  });
});

test("bonus edges: 24 and 24.0 valid, 24.1 RANGE, two decimals rejected", () => {
  assert.equal(run({ ...base, bonusMonths: "24" }).ok, true);
  assert.equal(run({ ...base, bonusMonths: "24.0" }).ok, true);
  assert.deepEqual(errorOf({ ...base, bonusMonths: "24.1" }), {
    code: "RANGE",
    field: "bonusMonths",
    row: null,
  });
  // A two-decimal value that fits the 4-unit raw capacity is a grammar
  // error; "24.55" is 5 units, so the capacity check (which the SPEC
  // orders before grammar) reports INPUT_LIMIT for it. See HANDOFF.md,
  // errata candidate 1, on the SPEC tests-section wording.
  assert.deepEqual(errorOf({ ...base, bonusMonths: "0.55" }), {
    code: "DECIMAL_FORMAT",
    field: "bonusMonths",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, bonusMonths: "24.55" }), {
    code: "INPUT_LIMIT",
    field: "bonusMonths",
    row: null,
  });
});

test("amount 0.01 on the hourly basis (SPEC tests section)", () => {
  // M = 0.01 x 240 = 2.4; monthly rounds to 2, hourly back to 0,
  // annualBase = 2.4 x 12 = 28.8 -> 29.
  assert.deepEqual(run({ sourceBasis: "hourly", amount: "0.01", bonusMonths: "0" }), {
    ok: true,
    result: { monthly: 2, daily: 0, hourly: 0, annualBase: 29, bonusAmount: 0, annualTotal: 29 },
  });
});

test("amount grammar rejects leading zeros, separators, spaces, signs, exponents", () => {
  for (const amount of ["040000", "40,000", " 40000", "40000 ", "40000.", ".5", "1e5", "+40000", "-1", "４００００"]) {
    assert.deepEqual(
      errorOf({ ...base, amount }),
      { code: "DECIMAL_FORMAT", field: "amount", row: null },
      `amount ${JSON.stringify(amount)}`,
    );
  }
  for (const bonusMonths of ["1.", ".5", "01", "1.55"]) {
    assert.deepEqual(
      errorOf({ ...base, bonusMonths }),
      { code: "DECIMAL_FORMAT", field: "bonusMonths", row: null },
      `bonusMonths ${JSON.stringify(bonusMonths)}`,
    );
  }
});

test("capacity precedes grammar; empty and surrogate checks sit between", () => {
  assert.deepEqual(errorOf({ ...base, amount: "9999999999999" }), {
    code: "INPUT_LIMIT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, sourceBasis: "monthlyX" }), {
    code: "INPUT_LIMIT",
    field: "sourceBasis",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, bonusMonths: "12345" }), {
    code: "INPUT_LIMIT",
    field: "bonusMonths",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, amount: "" }), { code: "EMPTY", field: "amount", row: null });
  assert.deepEqual(errorOf({ ...base, sourceBasis: "" }), {
    code: "EMPTY",
    field: "sourceBasis",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, amount: "\uD800" }), {
    code: "UNICODE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, bonusMonths: "1\uDC00" }), {
    code: "UNICODE",
    field: "bonusMonths",
    row: null,
  });
});

test("basis errors precede amount errors; amount errors precede bonus errors", () => {
  assert.deepEqual(errorOf({ sourceBasis: "weekly", amount: "0", bonusMonths: "25" }), {
    code: "ENUM",
    field: "sourceBasis",
    row: null,
  });
  assert.deepEqual(errorOf({ sourceBasis: "Monthly", amount: "40000", bonusMonths: "0" }), {
    code: "ENUM",
    field: "sourceBasis",
    row: null,
  });
  assert.deepEqual(errorOf({ sourceBasis: "monthly", amount: "0", bonusMonths: "25" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.amount;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, amount: 40000 }), schema);
  assert.deepEqual(errorOf(["monthly"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("monthly"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "amount", {
    enumerable: true,
    get() {
      return "40000";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("annual basis round-trips: annualTotal equals the entered annual amount", () => {
  // M = 123,456,789 / 15 exactly, so multiplying back is exact.
  const outcome = run({ sourceBasis: "annual", amount: "123456789", bonusMonths: "3" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.monthly, 8230453);
  assert.equal(outcome.result.annualTotal, 123456789);
});

test("property: outputs are non-negative integers and reconcile within NT$1", () => {
  const inputs = [
    { sourceBasis: "monthly", amount: "33333.33", bonusMonths: "0.5" },
    { sourceBasis: "daily", amount: "1234.56", bonusMonths: "2.5" },
    { sourceBasis: "hourly", amount: "187.25", bonusMonths: "13" },
    { sourceBasis: "annual", amount: "888888", bonusMonths: "0.1" },
    { sourceBasis: "monthly", amount: "1", bonusMonths: "24" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const { monthly, daily, hourly, annualBase, bonusAmount, annualTotal } = outcome.result;
    for (const value of [monthly, daily, hourly, annualBase, bonusAmount, annualTotal]) {
      assert.ok(Number.isSafeInteger(value) && value >= 0, `bad output ${value}`);
    }
    assert.ok(Math.abs(annualTotal - (annualBase + bonusAmount)) <= 1);
  }
});

test("property: on the monthly basis annualBase is exactly amount x 12 for whole amounts", () => {
  for (const amount of ["1", "7", "40000", "99999999"]) {
    const outcome = run({ sourceBasis: "monthly", amount, bonusMonths: "0" });
    assert.equal(outcome.ok, true);
    assert.equal(outcome.result.annualBase, Number(amount) * 12);
    assert.equal(outcome.result.monthly, Number(amount));
  }
});

test("display formatting groups thousands and never adds decimals", () => {
  assert.equal(formatAmount(0), "0");
  assert.equal(formatAmount(999), "999");
  assert.equal(formatAmount(1333), "1,333");
  assert.equal(formatAmount(560000), "560,000");
  assert.equal(formatAmount(10799998920), "10,799,998,920");
});
